export interface BeamConfig {
  id: string;
  length: number;
  profileType: string; // The user editable part inside "AUF'B'..."
  profileWidth: number; // The width part "125x50" -> 125
  loadCount: number; // e.g. 3
  loadWeight: number; // e.g. 400
}

export interface LevelConfig {
  id: string;
  label: string; // e.g. "A1 - A4"
  height: number;
}

export interface PlateData {
  id: string;
  quantity: number;

  // Header
  installationYear: number;
  projectNumber: number;
  sapNumberSuffix: string; // Last 5 digits
  rackNumber?: string; // Optional field

  // Row 1 & 2
  firstLevelHeight: number;
  subsequentLevels: LevelConfig[];

  // Row 3 (Beams)
  beams: BeamConfig[];

  // Row 4 (Frame)
  frameType: string; // Middle part
  frameDepth: number;
  frameHeight: number;

  // Row 5 (Calculated inputs)
  // We store manual overrides or calculated values here
  maxBayLoadOverride?: number; 
  highestLevelIndex: number; // e.g. if A7 is max, this is 7. Used for calculation.

  // Row 6 (Height)
  totalHeightOverride?: number;

  // Footer
  nextInspectionDate: string; // "Month Year" string
}

