import { BeamConfig, PlateData } from './types';

// Calculates Qmax for a single beam row
export const calculateQmax = (count: number, weight: number) => count * weight;

// Calculates Total Bay Load based on the logic: (Max Qmax) * (highestLevelIndex + 1)
export const calculateMaxBayLoad = (data: PlateData): number => {
  if (data.maxBayLoadOverride) return data.maxBayLoadOverride;

  let maxQmax = 0;
  data.beams.forEach(b => {
    const q = calculateQmax(b.loadCount, b.loadWeight);
    if (q > maxQmax) maxQmax = q;
  });

  // Formula: Qmax * (A_max + 1)
  // Logic: +1 accounts for the ground level or first level depending on exact engineering logic, 
  // but prompt says "A7 + 1" implies Level Index + 1.
  return maxQmax * (data.highestLevelIndex + 1);
};

// Calculates Total Height based on the logic: First Level + Sum of all subsequent levels
// Note: This is an approximation. If A1-A4 is 1250mm, it implies 4 levels of 1250mm?
// The prompt says "Suma z wysokości A + A1 + A2...". 
// Usually A1-A4 means levels 1,2,3,4. 
// We will use a simple sum of entered heights for now, but user can override.
export const calculateTotalHeight = (data: PlateData): number => {
  if (data.totalHeightOverride) return data.totalHeightOverride;

  // Since we don't strictly know how many levels are in "A1-A4" without parsing string,
  // we default to Sum of Unique Heights * (Highest Level / count of ranges).
  // A safer default for the "Automatic" view is usually Rack Height = Frame Height - Offset?
  // Let's rely on the user filling the "Frame Height" for the Frame row, 
  // and for this "Total Height" row, let's sum: FirstLevel + (HighestLevel * MaxSubsequentHeight).

  // Actually, standard logic is often First Level + (Number of other levels * Pitch).
  // Let's try: First Level + (Highest Level Index * 1000??). 
  // Given ambiguity, we return 0 so user is forced to verify or we set it to FrameHeight roughly.
  // Best approach based on prompt: "Suma z wysokości A + A1...".
  // If user enters "A1-A4 = 1250", we assume 4 levels of 1250.
  // Let's just use the Frame Height as a sensible default since the rack height usually matches frame height close enough.
  return data.frameHeight - 150; // Just a placeholder formula
};

export const formatPrice = (val: number) => val.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ");

import React from 'react';
import { PlateData } from '../types';
import { calculateQmax, calculateMaxBayLoad } from '../utils';

