        </div>

        {/* Row 3: Beam Rows */}
        {data.beams.map((beam) => {
          const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
          return (
            <div key={beam.id} className={`flex ${borderThin} border-l-0 border-r-0`}>
              <div className={`w-[25%] flex justify-between px-4 text-xl ${textBold} border-r-black border-r-2`}>
