import React from 'react';
import { PlateData, BeamConfig, LevelConfig } from '../types';
import { Plus, Trash2, RotateCcw } from 'lucide-react';
import { calculateMaxBayLoad } from '../utils';

interface Props {
  data: PlateData;
  onChange: (data: PlateData) => void;
  onDuplicate: () => void;
  onRemove: () => void;
}

export const PlateEditor: React.FC<Props> = ({ data, onChange, onDuplicate, onRemove }) => {

  const updateField = <K extends keyof PlateData>(field: K, value: PlateData[K]) => {
    onChange({ ...data, [field]: value });
  };

  const addLevel = () => {
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      label: 'A5 - A8',
      height: 1250
    };
    updateField('subsequentLevels', [...data.subsequentLevels, newLevel]);
  };

  const removeLevel = (id: string) => {
    updateField('subsequentLevels', data.subsequentLevels.filter(l => l.id !== id));
  };

  const updateLevel = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = data.subsequentLevels.map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels', updated);
  };

  const addBeam = () => {
    const newBeam: BeamConfig = {
      id: Math.random().toString(36).substr(2, 9),
      length: 2700,
      profileType: "E0485/15",
      profileWidth: 125,
      loadCount: 3,
      loadWeight: 400
    };
    updateField('beams', [...data.beams, newBeam]);
  };

  const removeBeam = (id: string) => {
    updateField('beams', data.beams.filter(b => b.id !== id));
  };

  const updateBeam = (id: string, field: keyof BeamConfig, value: string | number) => {
    const updated = data.beams.map(b => b.id === id ? { ...b, [field]: value } : b);
    updateField('beams', updated);
  };

  // Auto calculate bay load to show as placeholder
  const calculatedBayLoad = calculateMaxBayLoad(data);

  return (
    <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200 space-y-6">
      <div className="flex justify-between items-center border-b pb-4">
        <h2 className="text-xl font-bold text-gray-800">Edycja Tabliczki</h2>
        <div className="space-x-2">
          <button onClick={onDuplicate} className="text-sm bg-blue-100 text-blue-700 px-3 py-1 rounded hover:bg-blue-200">Duplikuj</button>
          <button onClick={onRemove} className="text-sm bg-red-100 text-red-700 px-3 py-1 rounded hover:bg-red-200">Usuń</button>
        </div>
      </div>

      {/* Global Config */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase">Ilość sztuk</label>
          <input 
            type="number" 
            min="1"
            value={data.quantity}
            onChange={(e) => updateField('quantity', parseInt(e.target.value) || 1)}
            className="w-full mt-1 border border-gray-300 rounded p-2 focus:ring-2 focus:ring-blue-500 outline-none"
          />
        </div>
      </div>

      {/* Header Info */}
      <section>
        <h3 className="text-sm font-bold text-gray-700 bg-gray-50 p-2 rounded mb-2">Nagłówek</h3>
        <div className="grid grid-cols-2 gap-4">
           <div>
            <label className="label">Rok Instalacji</label>
            <input 
              type="number"
              value={data.installationYear}
              onChange={(e) => updateField('installationYear', parseInt(e.target.value))}
              className="input-field"
            />
          </div>
          <div>
            <label className="label">Nr Regału (Opcjonalnie)</label>
            <input 
              type="text"
              value={data.rackNumber || ''}
              onChange={(e) => updateField('rackNumber', e.target.value)}
              className="input-field"
              placeholder="np. R-01"
            />
          </div>
          <div>
            <label className="label">Nr Projektu</label>
            <input 
              type="number"
              value={data.projectNumber}
              onChange={(e) => updateField('projectNumber', parseInt(e.target.value))}
              className="input-field"
            />
          </div>
           <div>
            <label className="label">SAP (Końcówka)</label>
            <div className="flex items-center">
              <span className="text-gray-500 mr-1 text-sm">46120</span>
              <input 
                type="text"
                maxLength={5}
                value={data.sapNumberSuffix}
                onChange={(e) => updateField('sapNumberSuffix', e.target.value)}
                className="input-field"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Levels */}
      <section>
        <h3 className="text-sm font-bold text-gray-700 bg-gray-50 p-2 rounded mb-2">Poziomy Belkowe</h3>
        <div className="grid grid-cols-2 gap-4 mb-2">
           <div>
            <label className="label">Wys. 1 poziomu (A)</label>
            <div className="flex items-center">
              <input 
                type="number"
                value={data.firstLevelHeight}
                onChange={(e) => updateField('firstLevelHeight', parseInt(e.target.value))}
                className="input-field"
              />
              <span className="ml-1 text-xs text-gray-500">mm</span>
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <label className="label block">Kolejne poziomy (Zakresy)</label>
          {data.subsequentLevels.map((lvl) => (
            <div key={lvl.id} className="flex gap-2 items-center">
               <input 
                type="text"
                value={lvl.label}
                onChange={(e) => updateLevel(lvl.id, 'label', e.target.value)}
                className="input-field w-1/3"
                placeholder="np. A1 - A4"
              />
               <input 
                type="number"
                value={lvl.height}
                onChange={(e) => updateLevel(lvl.id, 'height', parseInt(e.target.value))}
                className="input-field w-1/3"
                placeholder="Wysokość"
              />
              <span className="text-xs text-gray-500">mm</span>
              <button onClick={() => removeLevel(lvl.id)} className="text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
            </div>
          ))}
          <button onClick={addLevel} className="text-xs flex items-center text-blue-600 font-semibold mt-1">
            <Plus size={14} className="mr-1"/> Dodaj zakres
          </button>
        </div>
      </section>

      {/* Beams */}
      <section>
        <h3 className="text-sm font-bold text-gray-700 bg-gray-50 p-2 rounded mb-2">Trawersy (Row 3)</h3>
        {data.beams.map((beam) => (
          <div key={beam.id} className="border p-2 rounded mb-2 bg-gray-50">
             <div className="flex justify-between mb-2">
                <span className="text-xs font-bold text-gray-500">Trawers</span>
                <button onClick={() => removeBeam(beam.id)} className="text-red-500 hover:text-red-700"><Trash2 size={14} /></button>
             </div>
             <div className="grid grid-cols-3 gap-2 mb-2">
                <div>
                   <label className="label">Długość L</label>
                   <input 
                    type="number" 
                    value={beam.length}
                    onChange={(e) => updateBeam(beam.id, 'length', parseInt(e.target.value))}
                    className="input-field text-sm"
                  />
                </div>
                 <div className="col-span-2">
                   <label className="label">Profil (AUF'B'...)</label>
                   <div className="flex items-center gap-1">
                      <span className="text-xs text-gray-500 whitespace-nowrap">AUF'B'</span>
                      <input 
                        type="text" 
                        value={beam.profileType}
                        onChange={(e) => updateBeam(beam.id, 'profileType', e.target.value)}
                        className="input-field text-sm w-full"
                      />
                      <span className="text-xs text-gray-500">(</span>
                      <input 
                        type="number" 
                        value={beam.profileWidth}
                        onChange={(e) => updateBeam(beam.id, 'profileWidth', parseInt(e.target.value))}
                        className="input-field text-sm w-16"
                      />
                      <span className="text-xs text-gray-500">x50)</span>
                   </div>
                </div>
             </div>
             <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="label">Ilość (Count)</label>
                  <input type="number" value={beam.loadCount} onChange={e => updateBeam(beam.id, 'loadCount', parseInt(e.target.value))} className="input-field text-sm" />
                </div>
                <div>
                  <label className="label">Waga (Weight kg)</label>
                  <input type="number" value={beam.loadWeight} onChange={e => updateBeam(beam.id, 'loadWeight', parseInt(e.target.value))} className="input-field text-sm" />
                </div>
             </div>
          </div>
        ))}
         <button onClick={addBeam} className="text-xs flex items-center text-blue-600 font-semibold mt-1">
            <Plus size={14} className="mr-1"/> Dodaj profil
          </button>
      </section>

       {/* Frame */}
       <section>
        <h3 className="text-sm font-bold text-gray-700 bg-gray-50 p-2 rounded mb-2">Rama (Row 4)</h3>
        <div className="flex items-center gap-1">
           <span className="font-mono text-sm">STD'B'</span>
           <input 
            type="text" 
            value={data.frameType}
            onChange={(e) => updateField('frameType', e.target.value)}
            className="input-field w-16 text-center"
            placeholder="Typ"
           />
           <span className="font-mono">'</span>
           <input 
            type="number" 
            value={data.frameDepth}
            onChange={(e) => updateField('frameDepth', parseInt(e.target.value))}
            className="input-field w-20 text-center"
            placeholder="Głęb."
           />
           <span className="font-mono">'</span>
           <input 
            type="number" 
            value={data.frameHeight}
            onChange={(e) => updateField('frameHeight', parseInt(e.target.value))}
            className="input-field w-20 text-center"
            placeholder="Wys."
           />
        </div>
      </section>

      {/* Calculations / Summary */}
      <section>
        <h3 className="text-sm font-bold text-gray-700 bg-gray-50 p-2 rounded mb-2">Podsumowanie i Obliczenia</h3>

        {/* Highest Level Logic */}
        <div className="mb-4">
           <label className="label">Najwyższy nr poziomu (do obliczeń Qp)</label>
           <p className="text-[10px] text-gray-500 mb-1">Np. jeśli masz poziomy A1-A4, wpisz 4.</p>
           <input 
            type="number"
            value={data.highestLevelIndex}
            onChange={(e) => updateField('highestLevelIndex', parseInt(e.target.value))}
            className="input-field"
           />
        </div>

        <div className="grid grid-cols-1 gap-4">
          <div className="border p-2 rounded bg-gray-50">
            <div className="flex justify-between items-center mb-1">
              <label className="label mb-0">Max Obciążenie Pola (Qp)</label>
              <button 
                onClick={() => updateField('maxBayLoadOverride', undefined)} 
                title="Resetuj do auto"
                className="text-gray-400 hover:text-blue-500"
              >
                <RotateCcw size={14} />
              </button>
            </div>
            <input 
              type="number"
              value={data.maxBayLoadOverride ?? calculatedBayLoad}
              onChange={(e) => updateField('maxBayLoadOverride', parseInt(e.target.value))}
              className={`input-field ${data.maxBayLoadOverride ? 'border-yellow-400 bg-yellow-50' : 'text-gray-600'}`}
            />
            {!data.maxBayLoadOverride && <span className="text-[10px] text-gray-400">Obliczone automatycznie</span>}
          </div>

          <div className="border p-2 rounded bg-gray-50">
             <div className="flex justify-between items-center mb-1">
                <label className="label mb-0">Całkowita Wysokość (H)</label>
                 <button 
                  onClick={() => updateField('totalHeightOverride', undefined)} 
                  title="Resetuj do ramy"
                  className="text-gray-400 hover:text-blue-500"
                >
                  <RotateCcw size={14} />
                </button>
             </div>
             <input 
              type="number"
              value={data.totalHeightOverride || (data.frameHeight - 150)}
              onChange={(e) => updateField('totalHeightOverride', parseInt(e.target.value))}
              className={`input-field ${data.totalHeightOverride ? 'border-yellow-400 bg-yellow-50' : 'text-gray-600'}`}
             />
          </div>
        </div>
      </section>

      {/* Footer */}
      <section>
        <h3 className="text-sm font-bold text-gray-700 bg-gray-50 p-2 rounded mb-2">Stopka</h3>
        <div>
          <label className="label">Data Przeglądu</label>
          <input 
