import React, { useState, useEffect } from 'react';
import { PlateEditor } from './components/PlateEditor';
import { PlatePreview } from './components/PlatePreview';
import { PlateData, INITIAL_PLATE } from './types';
import { Printer, Plus, FileText, Layout } from 'lucide-react';

const App: React.FC = () => {
  // We manage an array of plate configurations
  const [plates, setPlates] = useState<PlateData[]>([{ ...INITIAL_PLATE }]);
  const [activePlateId, setActivePlateId] = useState<string>(plates[0].id);

  // Get active plate for editor
  const activePlate = plates.find(p => p.id === activePlateId) || plates[0];

  const updateActivePlate = (newData: PlateData) => {
    setPlates(prev => prev.map(p => p.id === newData.id ? newData : p));
  };

  const addNewPlateConfig = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate: PlateData = {
      ...INITIAL_PLATE,
      id: newId,
      quantity: 3 // Default quantity
    };
    setPlates(prev => [...prev, newPlate]);
    setActivePlateId(newId);
  };

  const duplicatePlate = (plate: PlateData) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate = { ...plate, id: newId };
    setPlates(prev => [...prev, newPlate]);
    setActivePlateId(newId);
  };

  const removePlate = (id: string) => {
    if (plates.length === 1) return; // Prevent deleting last one
    const newPlates = plates.filter(p => p.id !== id);
    setPlates(newPlates);
    if (activePlateId === id) {
      setActivePlateId(newPlates[0].id);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  // Generate the print queue based on quantities
  const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header - Hidden on Print */}
      <header className="bg-slate-800 text-white p-4 shadow-md no-print z-10 sticky top-0">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-2">
            <Layout className="w-6 h-6" />
            <h1 className="text-xl font-bold">Generator Tabliczek Znamionowych</h1>
          </div>
          <button 
            onClick={handlePrint}
            className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-lg font-semibold flex items-center gap-2 transition-colors"
          >
            <Printer size={20} />
            Eksportuj do PDF / Drukuj ({printQueue.length} szt.)
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden max-w-[1920px] mx-auto w-full">

        {/* Sidebar - List of Configs (No Print) */}
        <aside className="w-64 bg-white border-r border-gray-200 overflow-y-auto no-print flex flex-col">
          <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
             <span className="font-bold text-gray-700 text-sm">Twoje Projekty</span>
             <button onClick={addNewPlateConfig} className="bg-green-600 text-white p-1 rounded hover:bg-green-700" title="Dodaj nowy typ">
               <Plus size={16} />
             </button>
          </div>
          <div className="flex-1 p-2 space-y-2">
            {plates.map((plate, index) => (
              <div 
                key={plate.id}
                onClick={() => setActivePlateId(plate.id)}
                className={`p-3 rounded cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-sm' : 'border-gray-200 hover:border-blue-300'}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-gray-800 text-sm">Projekt #{index + 1}</div>
                  <div className="bg-gray-200 text-gray-600 text-xs px-2 py-0.5 rounded-full">{plate.quantity} szt.</div>
                </div>
                <div className="text-xs text-gray-500 truncate">Proj: {plate.projectNumber}</div>
                <div className="text-xs text-gray-500 truncate">{plate.frameType}'{plate.frameHeight}</div>
              </div>
            ))}
          </div>
        </aside>

        {/* Editor Area (No Print) */}
        <section className="flex-1 bg-gray-100 p-8 overflow-y-auto no-print">
          <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8">

            {/* Editor Form */}
            <div>
              <PlateEditor 
                data={activePlate} 
                onChange={updateActivePlate}
                onDuplicate={() => duplicatePlate(activePlate)}
                onRemove={() => removePlate(activePlate.id)}
              />
            </div>

            {/* Live Preview (Sticky) */}
            <div className="lg:sticky lg:top-4 h-fit">
              <div className="mb-2 flex justify-between items-center">
                <h3 className="text-gray-700 font-bold flex items-center gap-2">
                  <FileText size={18} /> Podgląd na żywo
                </h3>
                <span className="text-xs text-gray-400">Symulacja rozmiaru rzeczywistego (190x92mm)</span>
              </div>
              <div className="bg-white p-8 shadow-xl border border-gray-300 min-h-[500px] flex items-center justify-center overflow-auto">
                <div className="scale-100 origin-center">
                  <PlatePreview data={activePlate} />
                </div>
              </div>
            </div>

          </div>
        </section>

        {/* PRINT VIEW - Only visible when printing */}
        <div className="hidden print:block w-full">
           <div className="grid grid-cols-1 gap-y-0">
             {/* We need to render groups of 3 to force page breaks correctly. 
                 Since the plate height is fixed (92mm), 3 plates = 276mm, which fits A4 (297mm) nicely. */}
             {printQueue.map((plate, index) => (
                <div 
                  key={`${plate.id}-${index}`} 
                  className={`
                     w-full flex justify-center py-2
                     ${(index + 1) % 3 === 0 ? 'page-break mb-0' : 'mb-0'}
                  `}
                >
                  <PlatePreview data={plate} />
                </div>
             ))}
           </div>
        </div>

      </main>
    </div>
  );
};

export default App;

