          <div className={`w-[30%] px-2 py-0.5 text-center flex items-center justify-center bg-white`}>
            <span className="text-lg font-bold">A = {data.firstLevelHeight}</span>
            <span className="text-xs ml-0.5 mt-1">mm</span>
          </div>
        </div>

        {/* Row 2: Subsequent Levels */}
        <div className="flex-col shrink-0">
          {data.subsequentLevels.map((level, idx) => (
            <div key={level.id} className={`flex ${borderInner} border-black`}>
              <div className={`w-[70%] px-2 py-0.5 flex items-center ${borderRight}`}>
                <span className="text-xs font-bold uppercase">{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
              </div>
              <div className={`w-[30%] px-2 py-0.5 text-center flex items-center justify-center`}>
                <span className="text-base font-bold mr-2 text-gray-700">{level.label} =</span>
                <span className="text-lg font-bold">{level.height}</span>
                <span className="text-xs ml-0.5 mt-1">mm</span>
              </div>
            </div>
