  }).join('');

  return `
    <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
    <head>
      <meta charset="utf-8">
      <title>Export Word</title>
      <style>
        body { font-family: Arial, sans-serif; }
      </style>
    </head>
    <body>
      ${content}
    </body>
    </html>
  `;
};

import React, { useState, useEffect, useRef } from 'react';
import { PlateEditor } from './components/PlateEditor';
import { PlatePreview } from './components/PlatePreview';
import { PlateData, INITIAL_PLATE } from './types';
import { Printer, Plus, FileText, Layout, Layers, Sheet, Download, Upload, FileDown } from 'lucide-react';
import { generateWordHtml } from './utils';

const STORAGE_KEY = 'plateGeneratorData';

const App: React.FC = () => {
  const [plates, setPlates] = useState<PlateData[]>(() => {
    // Load from LocalStorage on init
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : [{ ...INITIAL_PLATE }];
    } catch (e) {
      console.error("Failed to load persistence", e);
      return [{ ...INITIAL_PLATE }];
    }
  });

  const [activePlateId, setActivePlateId] = useState<string>(plates[0].id);
  const [viewMode, setViewMode] = useState<'single' | 'sheet'>('single');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence effect
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(plates));
  }, [plates]);

  // Ensure activePlateId is valid
  useEffect(() => {
    if (!plates.find(p => p.id === activePlateId)) {
      setActivePlateId(plates[0]?.id || '');
    }
  }, [plates, activePlateId]);

  // Get active plate for editor
  const activePlate = plates.find(p => p.id === activePlateId) || plates[0];

  const updateActivePlate = (newData: PlateData) => {
    setPlates(prev => prev.map(p => p.id === newData.id ? newData : p));
  };

  const addNewPlateConfig = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate: PlateData = {
      ...INITIAL_PLATE,
      id: newId,
      quantity: 3 
    };
    setPlates(prev => [...prev, newPlate]);
    setActivePlateId(newId);
  };

  const duplicatePlate = (plate: PlateData) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate = { ...plate, id: newId };
    setPlates(prev => [...prev, newPlate]);
    setActivePlateId(newId);
  };

  const removePlate = (id: string) => {
    if (plates.length === 1) return;
    const newPlates = plates.filter(p => p.id !== id);
    setPlates(newPlates);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExport = () => {
    const dataStr = JSON.stringify(plates, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `projekty-tabliczki-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleWordExport = () => {
    // We generate an HTML string that Word interprets as a document
    // We expand the queue so users get exactly what they see in print preview (e.g. 3 copies of one plate)
    const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));
    const htmlContent = generateWordHtml(printQueue);

    const blob = new Blob(['\ufeff', htmlContent], {
      type: 'application/msword'
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `tabliczki-word-${new Date().toISOString().split('T')[0]}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json) && json.length > 0 && json[0].id) {
          setPlates(json);
          setActivePlateId(json[0].id);
        } else {
          alert("Nieprawidłowy format pliku JSON.");
        }
      } catch (err) {
        console.error(err);
        alert("Błąd podczas odczytu pliku.");
      }
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = '';
  };

  // Generate the print queue based on quantities
  const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));

  // Chunk for Sheet Preview (3 plates per page)
  const pages: PlateData[][] = [];
