        <div className="w-full px-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <Layout className="w-6 h-6" />
            <h1 className="text-xl font-bold hidden md:block">Generator Tabliczek Znamionowych</h1>
            <h1 className="text-xl font-bold md:hidden">Generator</h1>
          </div>

          <div className="flex items-center gap-2">
             <div className="flex items-center gap-1 mr-2 border-r border-slate-600 pr-3">
               <button 
                  onClick={handleWordExport} 
                  className="flex items-center gap-2 hover:bg-slate-700 px-3 py-2 rounded text-sm transition-colors text-blue-200 hover:text-white"
                  title="Eksportuj do Word (.doc)"
               >
                  <FileDown size={18} />
                  <span className="hidden lg:inline">Word</span>
               </button>

               <button 
                  onClick={handleExport} 
                  className="flex items-center gap-2 hover:bg-slate-700 px-3 py-2 rounded text-sm transition-colors text-gray-300 hover:text-white"
                  title="Zapisz do pliku"
               >
                  <Download size={18} />
                  <span className="hidden lg:inline">Zapisz</span>
               </button>
               <button 
                  onClick={handleImportClick} 
                  className="flex items-center gap-2 hover:bg-slate-700 px-3 py-2 rounded text-sm transition-colors text-gray-300 hover:text-white"
                  title="Wczytaj z pliku"
               >
                  <Upload size={18} />
                  <span className="hidden lg:inline">Wczytaj</span>
               </button>
                <input 
                  type="file" 
                  accept=".json" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  className="hidden" 
                />
             </div>

             <button 
              onClick={handlePrint}
              className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded font-semibold flex items-center gap-2 transition-colors text-sm"
             >
              <Printer size={18} />
              <span className="hidden sm:inline">Drukuj</span> ({printQueue.length})
             </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden w-full">

        {/* Sidebar - Updated (removed buttons footer) */}
        <aside className="w-64 bg-white border-r border-gray-200 overflow-y-auto no-print flex flex-col shrink-0 hidden md:flex">
          <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
             <span className="font-bold text-gray-700 text-sm">Twoje Projekty</span>
             <button onClick={addNewPlateConfig} className="bg-green-600 text-white p-1 rounded hover:bg-green-700" title="Dodaj nowy typ">
               <Plus size={16} />
             </button>
          </div>

          <div className="flex-1 p-2 space-y-2">
            {plates.map((plate, index) => (
              <div 
                key={plate.id}
                onClick={() => setActivePlateId(plate.id)}
                className={`p-3 rounded cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-sm' : 'border-gray-200 hover:border-blue-300'}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-gray-800 text-sm">Projekt #{index + 1}</div>
                  <div className="bg-gray-200 text-gray-600 text-xs px-2 py-0.5 rounded-full">{plate.quantity} szt.</div>
                </div>
                <div className="text-xs text-gray-500 truncate">Proj: {plate.projectNumber}</div>
                <div className="text-xs text-gray-500 truncate">{plate.frameType}'{plate.frameHeight}</div>
              </div>
            ))}
          </div>
        </aside>

        {/* Editor Area (No Print) */}
        <section className="flex-1 bg-gray-100 p-4 md:p-8 overflow-y-auto no-print">
          <div className="w-full max-w-[1800px] mx-auto grid grid-cols-1 xl:grid-cols-2 gap-8">

            {/* Editor Form */}
            <div className="w-full">
               {/* Mobile Project Selector */}
               <div className="md:hidden mb-4 bg-white p-2 rounded border">
                  <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Wybierz projekt</label>
                  <div className="flex gap-2 overflow-x-auto pb-2">
                    {plates.map((plate, idx) => (
                      <button 
                        key={plate.id}
                        onClick={() => setActivePlateId(plate.id)}
                        className={`px-3 py-1 rounded text-sm whitespace-nowrap ${activePlateId === plate.id ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
                      >
                        Projekt {idx+1}
                      </button>
                    ))}
                    <button onClick={addNewPlateConfig} className="bg-green-600 text-white px-2 py-1 rounded">
                      <Plus size={16} />
                    </button>
                  </div>
               </div>

              {activePlate && (
                <PlateEditor 
                  data={activePlate} 
                  onChange={updateActivePlate}
                  onDuplicate={() => duplicatePlate(activePlate)}
                  onRemove={() => removePlate(activePlate.id)}
                />
              )}
            </div>

            {/* Live Preview Column */}
            <div className="xl:sticky xl:top-4 h-fit">
              {/* Toolbar */}
              <div className="mb-2 flex justify-between items-center bg-white p-2 rounded border shadow-sm">
                <div className="flex items-center gap-2">
                   <h3 className="text-gray-700 font-bold flex items-center gap-2 text-sm">
                    <FileText size={18} /> Podgląd wydruku
                  </h3>
                </div>
                <div className="flex bg-gray-100 rounded p-1">
                   <button 
                    onClick={() => setViewMode('single')}
                    className={`flex items-center gap-1 px-3 py-1 rounded text-sm transition-all ${viewMode === 'single' ? 'bg-white shadow text-blue-600 font-bold' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     <Layers size={14} /> Pojedyncza
                   </button>
                   <button 
                    onClick={() => setViewMode('sheet')}
                    className={`flex items-center gap-1 px-3 py-1 rounded text-sm transition-all ${viewMode === 'sheet' ? 'bg-white shadow text-blue-600 font-bold' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     <Sheet size={14} /> Arkusze A4 ({pages.length})
