  // Ensure activePlateId is valid
  useEffect(() => {
    if (!plates.find(p => p.id === activePlateId)) {
      setActivePlateId(plates[0]?.id || '');
    }
  }, [plates, activePlateId]);

  // Get active plate for editor
  const activePlate = plates.find(p => p.id === activePlateId) || plates[0];

  const updateActivePlate = (newData: PlateData) => {
    setPlates(prev => prev.map(p => p.id === newData.id ? newData : p));
  };

  const addNewPlateConfig = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate: PlateData = {
      ...INITIAL_PLATE,
      id: newId,
      quantity: 3 
    };
    setPlates(prev => [...prev, newPlate]);
    setActivePlateId(newId);
  };

  const duplicatePlate = (plate: PlateData) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate = { ...plate, id: newId };
    setPlates(prev => [...prev, newPlate]);
    setActivePlateId(newId);
  };

  const removePlate = (id: string) => {
    if (plates.length === 1) return;
    const newPlates = plates.filter(p => p.id !== id);
    setPlates(newPlates);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExport = () => {
    const dataStr = JSON.stringify(plates, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `projekty-tabliczki-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleWordExport = async () => {
    // Use the native docx generation logic
    const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));

    try {
      const blob = await createDocxBlob(printQueue);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `tabliczki-${new Date().toISOString().split('T')[0]}.docx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Failed to generate DOCX", error);
      alert("Błąd podczas generowania pliku Word.");
    }
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json) && json.length > 0 && json[0].id) {
          setPlates(json);
          setActivePlateId(json[0].id);
        } else {
          alert("Nieprawidłowy format pliku JSON.");
        }
      } catch (err) {
        console.error(err);
        alert("Błąd podczas odczytu pliku.");
      }
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = '';
  };

  // Generate the print queue based on quantities
  const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));

  // Chunk for Sheet Preview (3 plates per page)
  const pages: PlateData[][] = [];
  for (let i = 0; i < printQueue.length; i += 3) {
    pages.push(printQueue.slice(i, i + 3));
  }

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header - Updated with buttons */}
      <header className="bg-slate-800 text-white p-3 shadow-md no-print z-10 sticky top-0">
        <div className="w-full px-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <Layout className="w-6 h-6" />
            <h1 className="text-xl font-bold hidden md:block">Generator Tabliczek Znamionowych</h1>
            <h1 className="text-xl font-bold md:hidden">Generator</h1>
          </div>

          <div className="flex items-center gap-2">
             <div className="flex items-center gap-1 mr-2 border-r border-slate-600 pr-3">
               <button 
                  onClick={handleWordExport} 
                  className="flex items-center gap-2 hover:bg-slate-700 px-3 py-2 rounded text-sm transition-colors text-blue-200 hover:text-white"
                  title="Eksportuj do Word (.docx)"
               >
                  <FileDown size={18} />
                  <span className="hidden lg:inline">Word</span>
               </button>

               <button 
                  onClick={handleExport} 
                  className="flex items-center gap-2 hover:bg-slate-700 px-3 py-2 rounded text-sm transition-colors text-gray-300 hover:text-white"
                  title="Zapisz do pliku"
               >
                  <Download size={18} />
                  <span className="hidden lg:inline">Zapisz</span>
               </button>
               <button 
                  onClick={handleImportClick} 
                  className="flex items-center gap-2 hover:bg-slate-700 px-3 py-2 rounded text-sm transition-colors text-gray-300 hover:text-white"
                  title="Wczytaj z pliku"
               >
                  <Upload size={18} />
                  <span className="hidden lg:inline">Wczytaj</span>
               </button>
                <input 
                  type="file" 
                  accept=".json" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  className="hidden" 
                />
             </div>

             <button 
              onClick={handlePrint}
              className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded font-semibold flex items-center gap-2 transition-colors text-sm"
             >
              <Printer size={18} />
              <span className="hidden sm:inline">Drukuj</span> ({printQueue.length})
             </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden w-full">

        {/* Sidebar - Updated (removed buttons footer) */}
        <aside className="w-64 bg-white border-r border-gray-200 overflow-y-auto no-print flex flex-col shrink-0 hidden md:flex">
          <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
             <span className="font-bold text-gray-700 text-sm">Twoje Projekty</span>
             <button onClick={addNewPlateConfig} className="bg-green-600 text-white p-1 rounded hover:bg-green-700" title="Dodaj nowy typ">
               <Plus size={16} />
             </button>
          </div>

          <div className="flex-1 p-2 space-y-2">
            {plates.map((plate, index) => (
              <div 
                key={plate.id}
                onClick={() => setActivePlateId(plate.id)}
                className={`p-3 rounded cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-sm' : 'border-gray-200 hover:border-blue-300'}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-gray-800 text-sm">Projekt #{index + 1}</div>
                  <div className="bg-gray-200 text-gray-600 text-xs px-2 py-0.5 rounded-full">{plate.quantity} szt.</div>
                </div>
                <div className="text-xs text-gray-500 truncate">Proj: {plate.projectNumber}</div>
                <div className="text-xs text-gray-500 truncate">{plate.frameType}'{plate.frameHeight}</div>
              </div>
            ))}
          </div>
        </aside>

        {/* Editor Area (No Print) */}
        <section className="flex-1 bg-gray-100 p-4 md:p-8 overflow-y-auto no-print">
          <div className="w-full max-w-[1800px] mx-auto grid grid-cols-1 xl:grid-cols-2 gap-8">

            {/* Editor Form */}
            <div className="w-full">
               {/* Mobile Project Selector */}
               <div className="md:hidden mb-4 bg-white p-2 rounded border">
                  <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Wybierz projekt</label>
                  <div className="flex gap-2 overflow-x-auto pb-2">
                    {plates.map((plate, idx) => (
                      <button 
                        key={plate.id}
                        onClick={() => setActivePlateId(plate.id)}
                        className={`px-3 py-1 rounded text-sm whitespace-nowrap ${activePlateId === plate.id ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
                      >
                        Projekt {idx+1}
                      </button>
                    ))}
                    <button onClick={addNewPlateConfig} className="bg-green-600 text-white px-2 py-1 rounded">
                      <Plus size={16} />
                    </button>
                  </div>
               </div>

              {activePlate && (
                <PlateEditor 
                  data={activePlate} 
                  onChange={updateActivePlate}
                  onDuplicate={() => duplicatePlate(activePlate)}
                  onRemove={() => removePlate(activePlate.id)}
                />
              )}
            </div>

            {/* Live Preview Column */}
            <div className="xl:sticky xl:top-4 h-fit">
              {/* Toolbar */}
              <div className="mb-2 flex justify-between items-center bg-white p-2 rounded border shadow-sm">
                <div className="flex items-center gap-2">
                   <h3 className="text-gray-700 font-bold flex items-center gap-2 text-sm">
                    <FileText size={18} /> Podgląd wydruku
                  </h3>
                </div>
                <div className="flex bg-gray-100 rounded p-1">
                   <button 
                    onClick={() => setViewMode('single')}
                    className={`flex items-center gap-1 px-3 py-1 rounded text-sm transition-all ${viewMode === 'single' ? 'bg-white shadow text-blue-600 font-bold' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     <Layers size={14} /> Pojedyncza
                   </button>
                   <button 
                    onClick={() => setViewMode('sheet')}
                    className={`flex items-center gap-1 px-3 py-1 rounded text-sm transition-all ${viewMode === 'sheet' ? 'bg-white shadow text-blue-600 font-bold' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     <Sheet size={14} /> Arkusze A4 ({pages.length})
                   </button>
                </div>
              </div>

              {/* Viewport */}
              <div className="bg-gray-200/50 p-4 md:p-8 rounded-lg shadow-inner border border-gray-300 min-h-[500px] max-h-[85vh] overflow-auto flex justify-center">

                {viewMode === 'single' ? (
                   // Single Plate Mode
                  <div className="bg-white shadow-xl scale-100 origin-top">
                     {activePlate && <PlatePreview data={activePlate} />}
                  </div>
                ) : (
                  // Full Sheet Mode
                  <div className="flex flex-col gap-8 scale-[0.6] sm:scale-[0.7] md:scale-[0.8] origin-top">
                    {pages.map((pagePlates, pageIdx) => (
                      <div 
                        key={pageIdx} 
                        className="bg-white shadow-2xl relative flex flex-col items-center"
                        style={{ width: '210mm', height: '297mm', padding: '10mm' }}
                      >
                         <div className="absolute top-2 left-2 text-gray-300 font-bold text-4xl select-none pointer-events-none">A4 - Strona {pageIdx + 1}</div>
                         {pagePlates.map((plate, idx) => (
                           <div key={`${plate.id}-${idx}`} className="mb-[5mm]">
                             <PlatePreview data={plate} />
                           </div>
                         ))}
                      </div>
                    ))}
                    {pages.length === 0 && <div className="text-gray-500">Brak elementów do wydruku.</div>}
                  </div>
                )}

              </div>
              <div className="text-center mt-2 text-xs text-gray-500">
                {viewMode === 'single' ? 'Podgląd aktywnej tabliczki (190x92mm)' : 'Symulacja układu na stronach A4'}
              </div>
            </div>

          </div>
        </section>

        {/* PRINT VIEW - STRICT PAGINATION */}
        <div className="hidden print:block w-full">
           {pages.map((pagePlates, pageIdx) => (
             <div 
                key={pageIdx} 
                className={`
                  w-full flex flex-col items-center 
                  ${pageIdx < pages.length - 1 ? 'page-break' : ''}
                `}
                style={{ paddingBottom: '20mm' }} // Ensure bottom margin on print
             >
                {pagePlates.map((plate, plateIdx) => (
                  <div key={`${plate.id}-${pageIdx}-${plateIdx}`} className="w-full flex justify-center mb-8 last:mb-0">
                    <PlatePreview data={plate} />
                  </div>
                ))}
             </div>
           ))}
        </div>

      </main>
    </div>
  );
};

export default App;

