import { BeamConfig, PlateData } from './types';
import { 
  Document, 
  Packer, 
  Paragraph, 
  Table, 
  TableRow, 
  TableCell, 
  WidthType, 
  TextRun, 
  BorderStyle, 
  AlignmentType,
  VerticalAlign,
  HeightRule
} from 'docx';

// Calculates Qmax for a single beam row
export const calculateQmax = (count: number, weight: number) => count * weight;

// Calculates Total Bay Load based on the logic: (Max Qmax) * (highestLevelIndex + 1)
export const calculateMaxBayLoad = (data: PlateData): number => {
  if (data.maxBayLoadOverride) return data.maxBayLoadOverride;

  let maxQmax = 0;
  data.beams.forEach(b => {
    const q = calculateQmax(b.loadCount, b.loadWeight);
    if (q > maxQmax) maxQmax = q;
  });

  return maxQmax * (data.highestLevelIndex + 1);
};

export const calculateTotalHeight = (data: PlateData): number => {
  if (data.totalHeightOverride) return data.totalHeightOverride;
  return data.frameHeight - 150; 
};

export const formatPrice = (val: number) => val.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ");

// Format "YYYY-MM" to "MonthName YYYY" in Polish
export const formatMonthYear = (isoMonth: string): string => {
  if (!isoMonth) return "";
  try {
    const [year, month] = isoMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    // Upper case first letter
    const formatted = date.toLocaleString('pl-PL', { month: 'long', year: 'numeric' });
    return formatted.charAt(0).toUpperCase() + formatted.slice(1);
  } catch (e) {
    return isoMonth;
  }
};

// --- DOCX GENERATION ---

// Helper to create a bold text run
const boldText = (text: string | number, size: number = 20, color?: string) => new TextRun({ 
  text: String(text), 
  bold: true, 
  size: size, 
  font: "Arial", 
  color: color 
});
const normalText = (text: string | number, size: number = 20) => new TextRun({ text: String(text), size: size, font: "Arial" });

// Helper to create a standard bordered cell
const createCell = (content: Paragraph[], colSpan: number = 1, shading: string = "FFFFFF", borders = true) => {
  return new TableCell({
    children: content,
    columnSpan: colSpan,
    shading: { fill: shading },
    verticalAlign: VerticalAlign.CENTER,
    margins: { top: 60, bottom: 60, left: 100, right: 100 }, // Twist margins
    borders: borders ? {
      top: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      left: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      right: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
    } : undefined
  });
};

const createPlateTable = (data: PlateData) => {
  const totalBayLoad = calculateMaxBayLoad(data);
  const formattedDate = formatMonthYear(data.nextInspectionDate);
  const rackHeight = data.totalHeightOverride || (data.frameHeight - 150);
  const hasSecondConfig = (data.firstLevelHeight2 !== undefined && data.firstLevelHeight2 !== null) || (data.subsequentLevels2 && data.subsequentLevels2.length > 0);

  const rows: TableRow[] = [];

  // --- Header Row ---
  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("ROK INSTALACJI", 14)], alignment: AlignmentType.LEFT }),
          new Paragraph({ children: [boldText(data.installationYear, 32)], alignment: AlignmentType.LEFT }),
        ],
        width: { size: 40, type: WidthType.PERCENTAGE },
        borders: { bottom: { style: BorderStyle.SINGLE, size: 4 } }
      }),
      new TableCell({
        children: [
          new Paragraph({ 
            children: [
              ...(data.rackNumber ? [boldText(`NR: ${data.rackNumber}  `, 24)] : []),
              boldText(data.customerName.toUpperCase(), 24)
            ], 
            alignment: AlignmentType.RIGHT 
          }),
          new Paragraph({ 
            children: [
              normalText("PROJEKT: ", 16),
              boldText(data.projectNumber, 22),
              normalText("  SAP: ", 16),
              boldText(`46120${data.sapNumberSuffix}`, 22)
            ], 
            alignment: AlignmentType.RIGHT 
          }),
        ],
        width: { size: 60, type: WidthType.PERCENTAGE },
        borders: { bottom: { style: BorderStyle.SINGLE, size: 4 } }
      })
    ]
  }));

  // Spacer row
  rows.push(new TableRow({ height: { value: 100, rule: HeightRule.EXACT }, children: [new TableCell({ children: [], columnSpan: 2, borders: { top: { style: BorderStyle.NIL }, bottom: { style: BorderStyle.NIL }, left: { style: BorderStyle.NIL }, right: { style: BorderStyle.NIL } } })] }));

  // --- Main Data Table (Nested) ---
  const contentRows: TableRow[] = [];

  // 1. Level 1 Height
  if (!hasSecondConfig) {
     contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("MAX. WYSOKOŚĆ 1. POZIOMU", 18)] })], 2, "F3F4F6"),
        createCell([new Paragraph({ children: [boldText(`A = ${data.firstLevelHeight} mm`, 24)], alignment: AlignmentType.CENTER })], 2)
      ]
    }));
  } else {
     contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("MAX. WYSOKOŚĆ 1. POZIOMU", 18)] })], 2, "F3F4F6"),
        createCell([new Paragraph({ children: [boldText(`A=${data.firstLevelHeight} mm`, 20)], alignment: AlignmentType.CENTER })], 1),
        createCell([new Paragraph({ children: [data.firstLevelHeight2 ? boldText(`A=${data.firstLevelHeight2} mm`, 20) : normalText('')], alignment: AlignmentType.CENTER })], 1)
      ]
    }));
  }


  // 2. Subsequent Levels
  if (!hasSecondConfig) {
     data.subsequentLevels.forEach((lvl, idx) => {
      contentRows.push(new TableRow({
        children: [
          createCell([new Paragraph({ children: [boldText(idx === 0 ? "KOLEJNE POZIOMY" : "", 16)] })], 2),
          createCell([new Paragraph({ children: [normalText(`${lvl.label} = `, 18), boldText(`${lvl.height} mm`, 22)], alignment: AlignmentType.CENTER })], 2)
        ]
      }));
    });
  } else {
    // Dual Config Rows
    const count1 = data.subsequentLevels.length;
    const count2 = data.subsequentLevels2 ? data.subsequentLevels2.length : 0;
    const maxRows = Math.max(count1, count2);

    for (let i = 0; i < maxRows; i++) {
       const l1 = data.subsequentLevels[i];
       const l2 = data.subsequentLevels2 ? data.subsequentLevels2[i] : undefined;

       const cell1Content = l1 ? [normalText(`${l1.label}=`, 16), boldText(`${l1.height}`, 18)] : [];
       const cell2Content = l2 ? [normalText(`${l2.label}=`, 16), boldText(`${l2.height}`, 18)] : [];

       contentRows.push(new TableRow({
        children: [
          createCell([new Paragraph({ children: [boldText(i === 0 ? "KOLEJNE POZIOMY" : "", 16)] })], 2),
          createCell([new Paragraph({ children: cell1Content, alignment: AlignmentType.CENTER })], 1),
          createCell([new Paragraph({ children: cell2Content, alignment: AlignmentType.CENTER })], 1)
        ]
      }));
    }
  }


  // 3. Beams Header
  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("MAKSYMALNE OBCIĄŻENIE PARY TRAWERSÓW", 18)], alignment: AlignmentType.CENTER })], 4, "FFFFFF")
    ]
  }));

  // 4. Beams Columns Header
  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("POZIOM", 14)], alignment: AlignmentType.CENTER })], 1, "F3F4F6"),
      createCell([new Paragraph({ children: [boldText("DŁ. (L)", 14)], alignment: AlignmentType.CENTER })], 1, "F3F4F6"),
      createCell([new Paragraph({ children: [boldText("PROFIL", 14)], alignment: AlignmentType.CENTER })], 1, "F3F4F6"),
      createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE", 14)], alignment: AlignmentType.CENTER })], 1, "F3F4F6"),
    ]
  }));

  // 5. Beams Rows
  data.beams.forEach(beam => {
    const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText(beam.levelLabel, 18)], alignment: AlignmentType.CENTER })]),
        createCell([new Paragraph({ children: [boldText(beam.length, 22)], alignment: AlignmentType.CENTER })]),
        createCell([new Paragraph({ children: [boldText(`AUF'B'${beam.profileType}`, 20), normalText(` (${beam.profileWidth}x50)`, 16)], alignment: AlignmentType.CENTER })]),
        createCell([new Paragraph({ children: [boldText(`Qmax= ${qMax} kg`, 22), normalText(` (${beam.loadCount} x ${beam.loadWeight} kg)`, 14)], alignment: AlignmentType.CENTER })]),
      ]
    }));
  });

  // 6. Frame
  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("RAMA", 16)], alignment: AlignmentType.CENTER })], 1, "F9FAFB"),
      createCell([new Paragraph({ children: [boldText(`STD'B'${data.frameType}'${data.frameDepth}'${data.frameHeight}`, 24)], alignment: AlignmentType.CENTER })], 3)
    ]
  }));

  // 7. Max Bay Load
  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE POLA", 18)] })], 2),
      createCell([new Paragraph({ children: [boldText("Qp=", 20, "FF0000")], alignment: AlignmentType.CENTER })], 1),
      createCell([new Paragraph({ children: [boldText(`${totalBayLoad} kg`, 24)], alignment: AlignmentType.CENTER })], 1)
    ]
  }));

  // 8. Height
  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("WYSOKOŚĆ REGAŁU", 18)] })], 2),
      createCell([new Paragraph({ children: [boldText("H=", 20)], alignment: AlignmentType.CENTER })], 1),
      createCell([new Paragraph({ children: [boldText(`${rackHeight} mm`, 24)], alignment: AlignmentType.CENTER })], 1)
    ]
  }));

  const dataTable = new Table({
    rows: contentRows,
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4 },
      bottom: { style: BorderStyle.SINGLE, size: 4 },
      left: { style: BorderStyle.SINGLE, size: 4 },
      right: { style: BorderStyle.SINGLE, size: 4 },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2 },
      insideVertical: { style: BorderStyle.SINGLE, size: 2 },
    }
  });

  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [dataTable],
        columnSpan: 2,
        borders: { top: { style: BorderStyle.NIL }, bottom: { style: BorderStyle.NIL }, left: { style: BorderStyle.NIL }, right: { style: BorderStyle.NIL } }
      })
    ]
  }));

  // Spacer
  rows.push(new TableRow({ height: { value: 100, rule: HeightRule.EXACT }, children: [new TableCell({ children: [], columnSpan: 2, borders: { top: { style: BorderStyle.NIL }, bottom: { style: BorderStyle.NIL }, left: { style: BorderStyle.NIL }, right: { style: BorderStyle.NIL } } })] }));

  // --- Footer ---
  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("ADRES DOSTAWCY:", 14)] }),
          new Paragraph({ children: [normalText("Jungheinrich Polska Sp. Z o.o.", 14)] }),
          new Paragraph({ children: [normalText("ul. Świerkowa 3 Bronisze k. Warszawy", 14)] }),
          new Paragraph({ children: [normalText("05-850 Ożarów Mazowiecki", 14)] }),
        ],
        width: { size: 40, type: WidthType.PERCENTAGE },
        borders: { top: { style: BorderStyle.SINGLE, size: 4 }, right: { style: BorderStyle.SINGLE, size: 2 } }
      }),
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("NASTĘPNY PRZEGLĄD TECHNICZNY", 16)], alignment: AlignmentType.LEFT }),
          new Paragraph({ children: [boldText(formattedDate, 32)], alignment: AlignmentType.LEFT }),
        ],
        width: { size: 60, type: WidthType.PERCENTAGE },
        verticalAlign: VerticalAlign.CENTER,
        borders: { top: { style: BorderStyle.SINGLE, size: 4 } }
      })
    ]
  }));

  // Gap between plates in the doc
  const plateContainer = new Table({
    rows: rows,
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.NIL },
      bottom: { style: BorderStyle.NIL },
      left: { style: BorderStyle.NIL },
      right: { style: BorderStyle.NIL },
      insideHorizontal: { style: BorderStyle.NIL },
      insideVertical: { style: BorderStyle.NIL }
    }
  });

  return [
    new Paragraph({ children: [] }), // spacing
    plateContainer,
    new Paragraph({ children: [], pageBreakBefore: true }) // Page break after each plate (or set of plates)
  ];
};

export const createDocxBlob = async (plates: PlateData[]): Promise<Blob> => {
  const allChildren: any[] = [];

  plates.forEach(plate => {
    const tableNodes = createPlateTable(plate);
    allChildren.push(...tableNodes);
  });

  const doc = new Document({
    sections: [{
      properties: {
        page: {
          margin: {
            top: 720,    // 0.5 inch (Twips)
            right: 720,  // 0.5 inch
            bottom: 720, // 0.5 inch
            left: 720    // 0.5 inch
          }
        }
      },
      children: allChildren
    }]
  });

  return await Packer.toBlob(doc);
};
